mapper.select:
SELECT c.id AS id, c.case_no AS code, c.case_name AS title, c.employee_name AS subtitle, c.case_type AS tag, u.user_name AS ownerName, c.update_time AS deletedTime FROM case_main c LEFT JOIN sys_user u ON u.user_id = c.handler_id WHERE c.deleted = 1
AND (c.case_no LIKE CONCAT('%', #{keyword}, '%') OR c.case_name LIKE CONCAT('%', #{keyword}, '%') OR c.employee_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY c.update_time DESC LIMIT #{offset}, #{size}

SELECT u.id AS id, u.user_id AS code, u.user_name AS title, d.dept_name AS subtitle, u.position AS tag, u.mobile AS ownerName, u.update_time AS deletedTime FROM sys_user u LEFT JOIN sys_dept d ON d.id = u.dept_id WHERE u.deleted = 1
AND (u.user_id LIKE CONCAT('%', #{keyword}, '%') OR u.user_name LIKE CONCAT('%', #{keyword}, '%') OR u.mobile LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY u.update_time DESC LIMIT #{offset}, #{size}

